import torch

def sparse_readout(scores, values, k, renorm=True):
    top = scores.topk(k, dim=-1)
    w = torch.softmax(top.values, dim=-1) if renorm else torch.exp(top.values)
    v = values.gather(-2, top.indices.unsqueeze(-1).expand(*top.indices.shape, values.shape[-1]))
    return (w.unsqueeze(-1) * v).sum(-2)

def hybrid_cost(n, L_eff=34, L_full=11, c1=1.0, c2=1.0):
    # 近似量级：高效层 ~O(n)，全量层 ~O(n^2)
    return c1 * L_eff * n + c2 * L_full * n ** 2

import torch

def linear_attn(q, k, v, gamma=0.99):
    S = torch.zeros(k.shape[-1], v.shape[-1])
    outs = []
    for t in range(q.shape[0]):
        S = gamma * S + torch.outer(k[t], v[t])   # 状态更新（写）
        outs.append(q[t] @ S)                     # 读出
    return torch.stack(outs)

import torch

def prefix_semantic_loss(head, tokens, dino_feat, weights=None):
    # tokens: [B, K, D]，逐前缀重建语义特征
    feats = torch.stack([head(tokens[:, :j + 1]) for j in range(tokens.shape[1])], 1)
    target = dino_feat.detach()                      # stop-gradient
    loss = ((feats - target.unsqueeze(1)) ** 2).mean(-1)
    if weights is not None:
        loss = loss * weights
    return loss.mean()

import torch, torch.nn.functional as F

def align_at_noise(decode_sem, dinofeat, z, eps_t):
    pred = decode_sem(z, eps_t)                    # 给定噪声水平的语义读出
    return F.cosine_similarity(pred, dinofeat.detach(), dim=-1).mean()
